source('webapp/backend/helpers/utils.R');source('webapp/backend/helpers/figure_method_rules.R');source('webapp/backend/helpers/plot_theme.R');source('webapp/backend/helpers/analysis_figures.R');source('webapp/backend/helpers/ordination_figures.R')
set.seed(231);d<-data.frame(sample=paste0('S',1:28),x=c(rnorm(12),rnorm(12,2),rnorm(4)),y=c(rnorm(12),rnorm(12,-1),rnorm(4)),group=c(rep('A',12),rep('B',12),rep('Missing group',4)),group_missing=c(rep(FALSE,24),rep(TRUE,4)))
t<-.ord_axis_tests(d,c('PC1','PC2'));expected<-vapply(c('x','y'),function(a)stats::wilcox.test(d[[a]][1:12],d[[a]][13:24],exact=FALSE,correct=TRUE)$p.value,numeric(1));stopifnot(isTRUE(all.equal(t$p_value,unname(expected))),isTRUE(all.equal(t$p_adjusted,unname(p.adjust(expected,'BH')))),all(t$n==24),all(t$n_missing==4))
w<-.ord_axis_tests(d,c('PC1','PC2'),'welch');stopifnot(isTRUE(all.equal(w$p_value[1],stats::t.test(d$x[1:12],d$x[13:24])$p.value)))
k<-d;k$group[9:16]<-'C';kt<-.ord_axis_tests(k,c('PC1','PC2'));stopifnot(kt$method[1]=='Kruskal-Wallis',isTRUE(all.equal(kt$p_value[1],stats::kruskal.test(k$x[1:24],k$group[1:24])$p.value)))
pairs<-.ord_pairwise(k,c('PC1','PC2'));stopifnot(nrow(pairs)==6,all(pairs$n_1>=2),all(pairs$n_2>=2))
for(i in seq_len(nrow(pairs))){col<-if(pairs$axis[i]=='PC1')'x' else 'y';a<-k[[col]][!k$group_missing&k$group==pairs$group_1[i]];b<-k[[col]][!k$group_missing&k$group==pairs$group_2[i]];stopifnot(abs(pairs$p_value[i]-wilcox.test(a,b,exact=FALSE,correct=TRUE)$p.value)<1e-14)}
stopifnot(max(abs(pairs$p_adjusted-p.adjust(pairs$p_value,'BH')))<1e-14)
reference<-.ord_pairwise(k,c('PC1','PC2'),'welch','reference','B');stopifnot(nrow(reference)==4,all(reference$group_1=='B'|reference$group_2=='B'),all(reference$method=='Welch t-test'))
stopifnot(nrow(.ord_pairwise(k,c('PC1','PC2'),mode='none'))==0,all(is.na(.ord_pairwise(flat<-transform(d,x=0,y=0),c('PC1','PC2'))$p_value)))
single<-k;single$group[1]<-'Single';eligible<-emp_ordination_figure(single,list(group='Group'),c('PC1','PC2'),c('PC1','PC2'),'Eligible groups');stopifnot(eligible$ellipses$type=='spread',eligible$test_scope$n_excluded==1,all(eligible$statistics$n==23),all(is.finite(eligible$statistics$p_value)),nrow(eligible$data)==28)
all_groups<-emp_ordination_figure(single,list(group='Group',test_scope='all'),c('PC1','PC2'),c('PC1','PC2'),'All groups');stopifnot(all(is.na(all_groups$statistics$p_value)),all_groups$test_scope$n_excluded==0)
e<-.ord_ellipses(d,'confidence',.95);stopifnot(length(e$audit)==2L,all(vapply(e$audit,function(z)z$drawn,logical(1))))
a<-e$data[e$data$group=='A',c('x','y')];radius<-mahalanobis(a,colMeans(d[1:12,c('x','y')]),cov(d[1:12,c('x','y')]));stopifnot(max(abs(radius-2*11/(12*10)*qf(.95,2,10)))<1e-10)
s<-.ord_ellipses(d,'spread',.95);stopifnot(max(abs(mahalanobis(s$data[s$data$group=='A',c('x','y')],colMeans(d[1:12,c('x','y')]),cov(d[1:12,c('x','y')]))-qchisq(.95,2)))<1e-10)
small<-d[1:3,];small$group<-c('single','pair','pair');small$y<-small$x
stopifnot(all(is.na(.ord_axis_tests(small,c('PC1','PC2'))$p_value)),all(!vapply(.ord_ellipses(small)$audit,function(z)z$drawn,logical(1))))
flat<-d;flat$x<-0;flat$y<-0;stopifnot(all(is.na(.ord_axis_tests(flat,c('PC1','PC2'))$p_value)))
unknown<-d;unknown$group_missing<-TRUE;stopifnot(all(is.na(.ord_axis_tests(unknown,c('PC1','PC2'))$p_value)),length(.ord_ellipses(unknown)$audit)==0)
proof<-'.local_run/verification/ordination-ellipses';dir.create(proof,recursive=TRUE,showWarnings=FALSE)
for(mode in c('manual','auto')){
 emp_viz_style_begin(list(export_size=list(width_mm=180,height_mm=160,dpi=150),publication=list(font_pt=8,min_font_pt=5,label_mode=mode,appearance=list(palette='npg',legend='bottom'))))
 fig<-emp_ordination_figure(d,list(group='Group',axis_test='auto'),c('PC1','PC2'),c('PC1','PC2'),'PCA ordination')
 stopifnot(emp_publication_plot(fig$plot,180/25.4,160/25.4)$patches$annotation$theme$legend.position=='bottom')
 stopifnot(nrow(fig$data)==28,identical(fig$data$x,d$x),identical(fig$data$y,d$y),fig$statistics$n_missing[1]==4)
 for(ext in c('png','pdf','svg'))emp_publication_export(fig$plot,file.path(proof,paste0(mode,'.',ext)),180/25.4,160/25.4,150)
}
emp_viz_style_begin(list(export_size=list(width_mm=120,height_mm=100,dpi=150),publication=list(font_pt=10,min_font_pt=5,label_mode='manual',appearance=list(legend='bottom'))))
compact<-emp_ordination_figure(k,list(group='Group'),c('PC1','PC2'),c('PC1','PC2'),'PCA ordination');for(ext in c('png','pdf'))emp_publication_export(compact$plot,file.path(proof,paste0('compact-pairwise.',ext)),120/25.4,100/25.4,150)
emp_viz_style_begin(list(export_size=list(width_mm=120,height_mm=100,dpi=150),publication=list(font_pt=6,min_font_pt=4,label_mode='manual')))
fig<-emp_ordination_figure(unknown,list(group='Group'),c('PC1','PC2'),c('PC1','PC2'),'All group labels missing');emp_publication_export(fig$plot,file.path(proof,'all-missing.pdf'),120/25.4,100/25.4)
cat('PASS exact axis P/BH, Welch/KW, Hotelling mean confidence and data ellipse geometry, missing / singleton / singular guards, frozen coordinates, layered vector composite\n')
